PHI=(1+5**0.5)/2
def is_cold(x,y):
    if x>y: x,y=y,x
    if x==0: return y==0
    n=y-x
    return int(n*PHI)==x and int(n*PHI*PHI)==y
# lose[x][y] = position (x,y) is a P-position
lose=[[False]*26 for _ in range(26)]
for x in range(26):
    for y in range(26):
        if x==0 and y==0:
            lose[x][y]=True; continue
        res=True
        for i in range(1,x+1):
            if lose[x-i][y]: res=False;break
        if res:
            for j in range(1,y+1):
                if lose[x][y-j]: res=False;break
        if res:
            for i in range(1,min(x,y)+1):
                if lose[x-i][y-i]: res=False;break
        lose[x][y]=res
