def ans_dp(a,b):
    if lose[a][b]: return 'LOSE'
    for i in range(a+1):
        for j in range(b+1):
            if i==0 and j==0: continue
            if lose[a-i][b-j]: return f'WIN {i} {j}'
    return 'LOSE'
def ans_f(a,b):
